messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: libtiff/tif_pixarlog.c
Line: 1343
Function: PixarLogEncode
Bug type: out-of-bounds-read
CWE: CWE-125
Explanation: The loop processes input in chunks of size llen (stride * imagewidth) but only checks that n <= rowsperstrip * llen. If n is not a multiple of llen (e.g., cc provides fewer bytes than a full row), the last iteration still calls horizontalDifference* with n=llen (lines 1348–1360), causing reads past the end of the input buffer bp. This leads to an out-of-bounds read on the final partial chunk.

Source context:
```c
     1303: {
     1304:     static const char module[] = "PixarLogEncode";
     1305:     TIFFDirectory *td = &tif->tif_dir;
     1306:     PixarLogState *sp = PixarLogEncoderState(tif);
     1307:     tmsize_t i;
     1308:     tmsize_t n;
     1309:     int llen;
     1310:     unsigned short *up;
     1311: 
     1312:     (void)s;
     1313: 
     1314:     switch (sp->user_datafmt)
     1315:     {
     1316:         case PIXARLOGDATAFMT_FLOAT:
     1317:             n = cc / sizeof(float); /* XXX float == 32 bits */
     1318:             break;
     1319:         case PIXARLOGDATAFMT_16BIT:
     1320:         case PIXARLOGDATAFMT_12BITPICIO:
     1321:         case PIXARLOGDATAFMT_11BITLOG:
     1322:             n = cc / sizeof(uint16_t); /* XXX uint16_t == 16 bits */
     1323:             break;
     1324:         case PIXARLOGDATAFMT_8BIT:
     1325:         case PIXARLOGDATAFMT_8BITABGR:
     1326:             n = cc;
     1327:             break;
     1328:         default:
     1329:             TIFFErrorExtR(tif, module,
     1330:                           "%" PRIu16 " bit input not supported in PixarLog",
     1331:                           td->td_bitspersample);
     1332:             return 0;
     1333:     }
     1334: 
     1335:     llen = sp->stride * td->td_imagewidth;
     1336:     /* Check against the number of elements (of size uint16_t) of sp->tbuf */
     1337:     if (n > ((tmsize_t)td->td_rowsperstrip * llen))
     1338:     {
     1339:         TIFFErrorExtR(tif, module, "Too many input bytes provided");
     1340:         return 0;
     1341:     }
     1342: 
>>>  1343:     for (i = 0, up = sp->tbuf; i < n; i += llen, up += llen)
     1344:     {
     1345:         switch (sp->user_datafmt)
     1346:         {
     1347:             case PIXARLOGDATAFMT_FLOAT:
     1348:                 horizontalDifferenceF((float *)bp, llen, sp->stride, up,
     1349:                                       sp->FromLT2);
     1350:                 bp += llen * sizeof(float);
     1351:                 break;
     1352:             case PIXARLOGDATAFMT_16BIT:
     1353:                 horizontalDifference16((uint16_t *)bp, llen, sp->stride, up,
     1354:                                        sp->From14);
     1355:                 bp += llen * sizeof(uint16_t);
     1356:                 break;
     1357:             case PIXARLOGDATAFMT_8BIT:
     1358:                 horizontalDifference8((unsigned char *)bp, llen, sp->stride, up,
     1359:                                       sp->From8);
     1360:                 bp += llen * sizeof(unsigned char);
     1361:                 break;
     1362:             default:
     1363:                 TIFFErrorExtR(tif, module,
     1364:                               "%" PRIu16 " bit input not supported in PixarLog",
     1365:                               td->td_bitspersample);
     1366:                 return 0;
